class Solution:
    def maximumTripletValue(self, nums: list[int]) -> int:
        import bisect
        n = len(nums)
        right = [0] * n
        right[-1] = nums[-1]
        for i in range(n - 2, -1, -1):
            right[i] = max(nums[i], right[i + 1])
        left_sorted = [nums[0]]
        ans = -float('inf')
        for j in range(1, n - 1):
            idx = bisect.bisect_left(left_sorted, nums[j]) - 1
            if idx >= 0 and right[j + 1] > nums[j]:
                ans = max(ans, left_sorted[idx] - nums[j] + right[j + 1])
            bisect.insort(left_sorted, nums[j])
        return ans if ans != -float('inf') else -1

class Solution {
public:
    int maximumTripletValue(vector<int>& nums) {
        int n = nums.size();
        vector<int> right(n);
        right[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; --i) right[i] = max(nums[i], right[i + 1]);
        set<int> left;
        left.insert(nums[0]);
        int ans = -1;
        for (int j = 1; j < n - 1; ++j) {
            auto it = left.lower_bound(nums[j]);
            if (it != left.begin() && right[j + 1] > nums[j]) {
                --it;
                ans = max(ans, *it - nums[j] + right[j + 1]);
            }
            left.insert(nums[j]);
        }
        return ans;
    }
};

class Solution {
    public int maximumTripletValue(int[] nums) {
        int n = nums.length;
        int[] right = new int[n];
        right[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; --i) right[i] = Math.max(nums[i], right[i + 1]);
        TreeSet<Integer> left = new TreeSet<>();
        left.add(nums[0]);
        int ans = -1;
        for (int j = 1; j < n - 1; ++j) {
            Integer leftVal = left.lower(nums[j]);
            if (leftVal != null && right[j + 1] > nums[j]) {
                ans = Math.max(ans, leftVal - nums[j] + right[j + 1]);
            }
            left.add(nums[j]);
        }
        return ans;
    }
}

var maximumTripletValue = function(nums) {
    const n = nums.length;
    const right = new Array(n);
    right[n - 1] = nums[n - 1];
    for (let i = n - 2; i >= 0; --i) right[i] = Math.max(nums[i], right[i + 1]);
    const left = [nums[0]];
    let ans = -1;
    for (let j = 1; j < n - 1; ++j) {
        let low = 0, high = left.length - 1, best = -1;
        while (low <= high) {
            const mid = (low + high) >> 1;
            if (left[mid] < nums[j]) {
                best = left[mid];
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        if (best !== -1 && right[j + 1] > nums[j]) {
            ans = Math.max(ans, best - nums[j] + right[j + 1]);
        }
        let ins = 0;
        while (ins < left.length && left[ins] < nums[j]) ins++;
        left.splice(ins, 0, nums[j]);
    }
    return ans;
};
